// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // authorized caller from the contract source
    address constant AUTH = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new C(); }

    // fuzz the array length and a single value; the fuzzer will construct arrays
    function testFuzz_property(address[] memory tos, uint256[] memory vals) public {
        // admissible domain: non-empty tos and matching lengths
        // keep wide: only require non-empty and same length
        if (tos.length == 0) return;
        if (tos.length != vals.length) return;

        // Make sure the target callee addresses are EOAs (the original contract performs a low-level call;
        // calling EOAs will succeed, so the call completes). We don't want reverts here — we are testing return value.
        // vm.assume not used to avoid restricting fuzzing too much; instead just ensure lengths match as above.

        // Prepare arrays for call
        // Execute transfer as the authorized caller
        vm.startPrank(AUTH);
        bool ok;
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // General rule: reference returns true (call completes and returns true) for all admissible inputs.
        // We assert that the call succeeded (did not revert) and returned true. For the reference contract this
        // is always satisfied; the mutant that returns false will make this assertion fail for some inputs
        // (specifically any admissible input where the call does not revert).
        assertTrue(ok);
    }
}

