pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address authorized = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new C(); }

    // fuzz the arrays so the fuzzer can find a case where the mutant returns false
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // admissible domain: caller must be the authorized address and arrays non-empty and same length
        vm.assume(_tos.length > 0 && _tos.length == v.length);

        // Ensure the authorized address has ETH so low-level calls to helper addresses (if any) won't fail due to lack of balance
        vm.deal(authorized, 1 ether);

        // Call as the authorized caller and capture the returned boolean
        bool ok;
        vm.prank(authorized);
        try c.transfer(_tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // If it reverts, treat as false (but for this contract both versions should not revert for admissible inputs)
            ok = false;
        }

        // The correct contract always returns true for any admissible input; the mutant will return false for some inputs.
        assertTrue(ok);
    }
}

