        fallback() external payable {
            // do nothing, implicitly returns true
        }
        receive() external payable {}
    }

    function setUp() public { c = new C(); }

    // fuzz parameters: an array of addresses (tos) and array of uints (v)
    function testFuzz_property(address[] memory tos, uint256[] memory vals) public {
