            ok = ret;
        } catch {
            ok = false;
        }

        // The universal property: for any admissible inputs (non-empty, matching lengths) called by the
        // authorized sender, the reference implementation returns true (ok == true). The mutant returns
        // false for some inputs, so this assert will pass on reference and fail on mutant for those inputs.
        assertTrue(ok);
