pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: array length and two uint values per entry; we fuzz a single value and length
    function testFuzz_property(uint256 len, uint256 v0) public {
        // keep length reasonable but allow zero which is invalid; we need non-empty to be admissible
        len = bound(len, 0, 8); // keep arrays small for gas
        vm.assume(len > 0);

        // Prepare arrays
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        // deploy a benign callee that always succeeds on low-level call
        BenignCallee cal = new BenignCallee();
        for (uint i = 0; i < len; i++) {
            tos[i] = address(cal);
            // spread values so fuzzer's single v0 influences all entries but not constant
            vals[i] = v0 + i;
        }

        // call as the authorized sender
        address authorized = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        // fund authorized so if any payable needed (not in C) it's available
        vm.deal(authorized, 1 ether);
        vm.prank(authorized);

        // capture the returned boolean via try/catch to read call success and return value
        bool ok;
        try c.transfer(tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            // should not revert because callee is benign
            ok = false;
        }

        // The reference contract always returns true for successful completion; assert the observed return is true.
        assertTrue(ok);
    }
}

// benign callee that always returns successfully to low-level calls
contract BenignCallee {
    fallback() external payable {
        // do nothing, succeed
    }
}

