pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the index that will cause the adversarial callee to return false for that index
    function testFuzz_property(uint256 badIndex, uint256 len, uint256 dummyAmount) public {
        // keep lengths reasonable but wide; require at least 1 recipient
        vm.assume(len > 0 && len < 20);
        // bound badIndex into [0, len-1]
        uint256 idx = badIndex % len;

        // prepare arrays
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        // deploy adversarial callee that returns false exactly for idx
        FailingCallee f = new FailingCallee(idx);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(f);
            vals[i] = dummyAmount + i + 1; // varied amounts
        }

        // make the caller the required authorized sender
        address auth = address(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        vm.prank(auth);

        // call transfer and capture whether it returned true/false (or reverted)
        bool ok;
        try c.transfer(tos, vals) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // GENERAL RULE: On the reference C, transfer(...) never returns false when it does not revert.
        // We assert that the call returned true (the reference always returns true for non-reverting calls).
        // The mutant (which returns false if a callee low-level call yielded false) will fail this
        // when the adversarial callee returns false for the chosen index.
        assertTrue(ok);
    }
}

// Adversarial callee: returns false (but does NOT revert) when called for the chosen index.
contract FailingCallee {
    uint256 public badIndex;
    uint256 public calls;
    constructor(uint256 _badIndex) payable {
        badIndex = _badIndex;
        calls = 0;
    }
    // emulate ERC20-like transferFrom selector: transferFrom(address,address,uint256)
    // We'll implement a fallback that inspects call count and returns false for badIndex.
    fallback() external payable returns (bytes memory) {
        // increment call counter
        uint256 current = calls;
        calls = current + 1;
        // if this is the bad call, return false (as 32-byte boolean false)
        if (current == badIndex) {
            bytes memory ret = abi.encode(false);
            return ret;
        }
        // otherwise return true
        return abi.encode(true);
    }
    // also provide receive to accept plain ether sends (not strictly needed)
    receive() external payable {}
}

