pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the number of recipients and an index that the adversarial callee will make its call return false for
    function testFuzz_property(uint256 n, uint256 badIndex) public {
        // keep n in a reasonable but wide bound: at least 1 and not too large
        uint256 len = bound(n, 1, 10);
        // construct arrays
        address[] memory tos = new address[](len);
        uint256[] memory vals = new uint256[](len);

        // deploy a callee that will return false when called with a particular index marker
        // we will place the helper's address into c's caddress slot by sending transfer calls where from is the stored from
        // but C already has caddress hardcoded; we instead rely on that hardcoded address being an EOA in test env
        // so we need to instead call c.transfer with tos that are the helper and amounts with an index marker encoded
        // The original C calls low-level caddress.call(..., from, _tos[i], amount)
        // The only way to influence the callee is to make the callee's address equal to the hardcoded caddress.
        // However the test requirement forbids changing C, so instead we deploy a helper at that exact address using vm.etch.

        // Create a helper that returns false on its fallback for the chosen marker; we will etch its bytecode to the hardcoded address.
        BadCallee helper = new BadCallee();

        // Hardcoded address from C source
        address target = 0x1f844685f7Bf86eFcc0e74D8642c54A257111923;
        // place the helper's runtime code at the target address so calls to that address hit our helper logic
        bytes memory code = address(helper).code;
        // write code to target
        vm.etch(target, code);

        // choose a bad index inside bounds
        uint256 idx = bound(badIndex, 0, len - 1);

        // fill arrays; we encode the index marker into the value so the helper can detect which call index it is
        for (uint256 i = 0; i < len; i++) {
            tos[i] = target; // calls go to the etched helper address
            // encode marker: if i == idx set value to 1 else 0
            vals[i] = (i == idx) ? 1 : 0;
        }

        // ensure msg.sender matches C.from
        address from = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(from);

        // call and capture whether it reverts or not; reference returns true (not false) for all non-reverting calls
        bool ok;
        try c.transfer(tos, vals) returns (bool r) {
            ok = r; // should be true for reference
        } catch {
            ok = false;
        }

        // General property: reference C never returns false on any non-reverting invocation; thus ok must be true.
        // The mutant that returns false when a low-level call returns false will violate this for some inputs (here our helper makes one call return false).
