// adversarial helper: its fallback will inspect calldata to decide whether to return false or true
contract BadCallee {
    fallback() external payable returns (bytes memory) {
        // calldata layout: selector(4) + from(32) + to(32) + amount(32)
        // we check the amount slot: if amount == 1 -> return false (i.e., return empty but with success=false cannot be done from solidity)
        // Instead, to simulate a low-level call returning false, we use SELFDESTRUCT to make subsequent calls fail? Not reliable.
        // Better: return normally but encode a boolean false as data so the caller's (bool ok,) = call(...) will set ok=true; however
        // low-level call success bit is controlled by whether this fallback reverts. To make call return false we revert.
        // So when amount == 1 we revert; but reference C ignores call failures (it does not revert on failed low-level calls) and continues and still returns true.
        // The mutant would detect the low-level call returning false only if the call returned false without revert; but a reverted callee makes the outer call revert too.
        // However the intended mutant change checks the boolean ok from call; to produce ok==false without revert, we must return normally but with no return data and simulate failure by using assembly to return with success=false — not possible.
        // Simpler: implement a fallback that returns successfully but the low-level call from C will see ok==true. To make ok==false we must make the call succeed=false which only happens when callee uses invalid opcode or runs out of gas and does not revert? Using revert with no reason still marks success=false but also bubbles? Actually low-level call does not bubble; call returns (false, data) when callee reverts. So reverting makes ok=false but does not revert caller. Good.
        // So: if amount == 1 revert to cause call to return ok=false; otherwise return normally.

        // read amount
        if (msg.data.length >= 4 + 32 + 32 + 32) {
            // amount is last 32 bytes
            uint256 amount;
            assembly { amount := calldataload(add(0x4, add(0x20, 0x40))) }
            if (amount == 1) {
                revert("bad");
            }
        }
        // otherwise return success
        return abi.encode(true);
    }
}

