// Minimal recorder that stores last amount passed as third arg of transferFrom selector
contract Recorder {
    uint256 public lastAmount;
    // selector matches transferFrom(address,address,uint256)
    fallback() external payable {
        // decode calldata: selector(4) + from(32) + to(32) + amount(32)
        if (msg.data.length >= 4 + 32*3) {
            // skip selector
            bytes memory b = msg.data[4:];
            uint256 amount;
            assembly { amount := mload(add(b, 64)) } // third word
            lastAmount = amount;
        }
    }
