// Factory used solely to produce bytecode for Recorder; its instance is deployed and then used by Deployer
contract RecorderFactory {
    function deploy() external returns (address) {
        Recorder r = new Recorder();
        return address(r);
    }
}

// Deployer that uses CREATE2 to put a minimal Recorder at the desired address
contract Deployer {
    // deploy the bytecode of a freshly created Recorder contract at the desired address
    // Note: This function deploys a Recorder via CREATE2 with a salt derived from target to place it at target
    // It delegates creation to a factory to obtain the bytecode to deploy.
    function deployAt(address target, address factory) external {
        // get runtime code of a Recorder by deploying temporarily then reading extcode
        address temp = RecorderFactory(factory).deploy();
        bytes memory code = addressToCode(temp);
        // compute salt so CREATE2 yields target
        bytes32 salt = bytes32(uint256(uint160(target)));
        address addr;
        assembly {
            addr := create2(0, add(code, 0x20), mload(code), salt)
        }
        // if create2 didn't land at target (unlikely collisions), done
        require(addr == target, "deploy failed");
    }

    function addressToCode(address a) internal view returns (bytes memory) {
        bytes memory o;
        assembly {
            let size := extcodesize(a)
            o := mload(0x40)
            mstore(0x40, add(o, and(add(add(size, 0x20), 0x1f), not(0x1f))))
            mstore(o, size)
            extcodecopy(a, add(o, 0x20), 0, size)
        }
        return o;
    }
}

